from html.parser import HTMLParser
from pathlib import Path
import re
from urllib.parse import urlsplit
import markdown
class Semantics(HTMLParser):
    def __init__(self):
        super().__init__()
        self.headings = []
        self.ids = []
        self.links = []
        self.tables = 0
        self.columns = 0
        self._link = None
    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        if 'id' in attributes:
            self.ids.append(attributes['id'])
        if re.fullmatch(r'h[1-6]', tag):
            self.headings.append(int(tag[1]))
        if tag == 'a' and 'href' in attributes:
            self._link = [attributes['href'], '']
        if tag == 'table':
            self.tables += 1
        if tag == 'th':
            self.columns += 1
    def handle_endtag(self, tag):
        if tag=='a' and self._link is not None:
            self.links.append(self._link)
            self._link = None
    def handle_data(self, data):
        if self._link is not None:
            self._link[1] += data

paths = [Path(p) for p in ('README.md','deliverables/accuracy.md','deliverables/verification.md','planning/plan.md')]
parsed = {}
for path in paths:
    md=markdown.Markdown(extensions=['tables','fenced_code','toc'])
    parser=Semantics()
    parser.feed(md.convert(path.read_text()))
    assert parser.headings[0] == 1 and parser.headings.count(1)==1
    assert all(b<=a+1 for a,b in zip(parser.headings,parser.headings[1:]))
    assert len(parser.ids)==len(set(parser.ids))
    assert all(name.strip() for _,name in parser.links)
    if path.name in ('accuracy.md','verification.md'):
        assert parser.tables and parser.columns >= 2*parser.tables
    parsed[path.resolve()] = parser
    print(f'{path}: {len(parser.headings)} headings, {len(parser.links)} named links, {parser.tables} tables')
for name, doc in parsed.items():
    for href, _ in doc.links:
        url=urlsplit(href)
        if url.scheme or not url.fragment: continue
        target=(name.parent/url.path).resolve() if url.path else name
        if target in parsed:
            assert url.fragment in parsed[target].ids, (name,href)
