"""Independent bounded workers with durable attempts and explicit recovery."""
from concurrent.futures import ThreadPoolExecutor
import shlex
import time
from .extract import prepare, settings
from .policy import route
from .providers import ProviderError


class Runner:
    def __init__(self, store, provider, workers=4, timeout=30, max_retries=0,
                 retry_delay=1, clock=time.time, sleep=time.sleep, config=None):
        if workers < 1 or timeout <= 0 or max_retries < 0 or retry_delay < 0:
            raise ValueError('invalid worker, timeout or retry configuration')
        self.store, self.provider = store, provider
        self.workers, self.timeout = workers, timeout
        self.max_retries, self.retry_delay = max_retries, retry_delay
        self.clock, self.sleep = clock, sleep
        self.config = settings(provider, config)
        self.config['timeout'] = timeout
        if hasattr(provider, 'root'):
            self.config['mock_responses'] = str(provider.root.resolve())

    def run(self, documents, force=False):
        attempts = [self.store.begin(doc, self.config, force) for doc in documents]
        self._execute([a for a in attempts if a is not None])
        return self.store.current()

    def _execute(self, attempts):
        with ThreadPoolExecutor(max_workers=self.workers) as pool:
            list(pool.map(self._work, dict.fromkeys(attempts)))

    def retry_command(self, document_id):
        args = ['python3', '-m', 'intake', 'retry', '--db', self.store.path, '--document', document_id]
        if self.provider.response_source == 'mock':
            args += ['--provider', 'mock', '--responses', str(self.provider.root.resolve())]
        return shlex.join(args)

    def _work(self, attempt):
        row = self.store.get(attempt)
        if not row:
            return
        delay = row['not_before'] - self.clock()
        if delay > 0:
            self.sleep(delay)
        while True:
            token = self.store.claim(attempt, now=self.clock(), lease=self.timeout + 5)
            if not token:
                return
            row = self.store.get(attempt)
            doc = row['document']
            try:
                # Use the persisted producing settings when resuming recorded work.
                prepared = prepare(doc, self.provider, row['settings'])
                result = dict(prepared, **route(doc, prepared['extraction']), error=None)
                result['settings'] = row['settings']
            except Exception as exc:
                if isinstance(exc, ProviderError) and exc.retryable and row['tries'] <= self.max_retries:
                    delay = self.retry_delay * (2 ** (row['tries'] - 1))
                    if not self.store.defer(attempt, token, self.clock() + delay):
                        return
                    self.sleep(delay)
                    continue
                message = str(exc).lower()
                category = 'provider-error' if isinstance(exc, ProviderError) else 'invalid-response'
                for word in ['refusal', 'incomplete', 'malformed', 'structure', 'quote']:
                    if word in message:
                        category = word
                        break
                result = {'extraction': None, 'status': 'error', 'owner': 'IT Service Desk',
                          'next_action': 'retry-extraction', 'error': f'{category}: extraction failed; inspect source and recorded provider settings, then retry',
                          'error_type': category, 'retry_command': self.retry_command(doc['document_id']),
                          'response_source': self.provider.response_source, 'settings': row['settings']}
            self.store.finish(attempt, result, token=token, now=self.clock())
            return

    def resume(self, attempts=None):
        rows = self.store.pending()
        if attempts is not None:
            rows = [row for row in rows if row['id'] in attempts]
        work = []
        for row in rows:
            changed = any(key in row['settings'] and row['settings'][key] != value for key, value in self.config.items())
            if changed:
                fresh = self.store.begin(row['document'], self.config, force=True)
                self.store.supersede(row['id'])
                work.append(fresh)
            else:
                work.append(row['id'])
        self._execute(work)
        return self.store.current()

    def retry(self, document_id):
        history = self.store.history(document_id)
        if not history:
            raise ValueError(f'unknown document: {document_id}')
        return self.run([history[-1]['document']], force=True)
"""Disk-scripted providers and injectable HTTP transport boundaries."""
from collections import deque
from copy import deepcopy
import json
from pathlib import Path
import threading


class ProviderError(ValueError):
    def __init__(self, message, retryable=False):
        super().__init__(message)
        self.retryable = retryable


class MockTransport:
    def __init__(self, root, responses, barriers=None):
        self.root = Path(root)
        self.responses = deque(responses)
        self.requests = []
        self.barriers = barriers or {}
        self.lock = threading.Lock()

    def __call__(self, request):
        with self.lock:
            self.requests.append(deepcopy(request))
            if not self.responses:
                raise ProviderError('unscripted transport call')
            name = self.responses.popleft()
        response = json.loads((self.root / name).read_text(encoding='utf-8'))
        if response.get('event') == 'file-block':
            gates = request.get('config', {}).get('mock_gates')
            if not gates:
                raise ProviderError('file-block fixture requires --mock-gates')
            FileEvent(Path(gates) / response['entered']).set()
            if not FileEvent(Path(gates) / response['barrier']).wait(request.get('config', {}).get('timeout', 30)):
                raise ProviderError('provider response timeout', True)
            response = json.loads((self.root / response['response']).read_text())
        if response.get('event') == 'block':
            if response.get('entered') in self.barriers:
                self.barriers[response['entered']].set()
            timeout = request.get('timeout', request.get('config', {}).get('timeout', 30))
            if not self.barriers[response['barrier']].wait(timeout):
                raise ProviderError('provider response timeout', True)
            response = json.loads((self.root / response['response']).read_text())
        if response.get('event') == 'error':
            raise ProviderError(response['error'], response.get('retryable', False))
        return response


class MockProvider:
    response_source = 'mock'

    def __init__(self, root, scripts=None, barriers=None):
        self.root = Path(root)
        if scripts is None:
            scripts = json.loads((self.root / 'manifest.json').read_text())
        self.scripts = {key: MockTransport(root, values, barriers) for key, values in scripts.items()}
        self.calls = []
        self.lock = threading.Lock()

    def complete(self, document, config=None):
        name = document['document_id']
        with self.lock:
            self.calls.append(name)
        if name not in self.scripts:
            raise ProviderError(f'unscripted document: {name}')
        return self.scripts[name]({'message': document.get('message', ''), 'config': config or {}})


class FileEvent:
    """Development-only cross-process barrier used by saved mock scenarios."""
    def __init__(self, path):
        self.path = Path(path)

    def set(self):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.path.touch()

    def wait(self, timeout):
        import time
        deadline = time.monotonic() + timeout
        while not self.path.exists():
            if time.monotonic() >= deadline:
                return False
            time.sleep(min(0.01, max(0, deadline - time.monotonic())))
        return True
